import {
  Object3D,
  Mesh,
  PlaneGeometry,
  LineSegments,
  EdgesGeometry,
  LineBasicMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  Color,
  Vector3
} from 'three/webgpu';
import {
  mix,
  uv,
  color,
  float,
  mul
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{position:[number,number,number],rotation:[number,number,number],scale:[number,number,number]}} scenePlacement
 * @property {{tierName:string,price:string,caption:string,features:string[],cta:string}} textContent
 * @property {{cinematicPrimitives:any[]}} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} primitives
 * @property {any} fontAtlas
 * @property {any} textureLoader
 * @property {any} glbLoader
 */

export default function createNode(config, ctx) {
  const root = new Object3D();

  // Apply scene placement
  const [px, py, pz] = config.scenePlacement.position || [0, 0, 0];
  const [rx, ry, rz] = config.scenePlacement.rotation || [0, 0, 0];
  const [sx, sy, sz] = config.scenePlacement.scale || [1, 1, 1];
  root.position.set(px, py, pz);
  root.rotation.set(rx, ry, rz);
  root.scale.set(sx, sy, sz);

  // Card dimensions
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const CORNER_RADIUS = 0.06;
  const BORDER_COLOR = 0x2a2a33;
  const BORDER_THICKNESS = 0.006;
  const HEADER_H = 0.08;
  const PADDING = 0.5;
  const FEATURE_ROW_H = 0.375;
  const FEATURE_GAP = 0.006;
  const CTA_W = 1.4;
  const CTA_H = 0.36;
  const CTA_OFFSET_FROM_BOTTOM = 0.5;

  // ---------- Card Plane ----------
  const cardGeometry = new PlaneGeometry(CARD_W, CARD_H, 1, 1);
  const cardMaterial = new MeshStandardNodeMaterial();
  cardMaterial.colorNode = color('#16161d');
  cardMaterial.metalness = 0.0;
  cardMaterial.roughness = 1.0;
  cardMaterial.clearcoat = 0.0;
  cardMaterial.transparent = true;
  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  root.add(cardMesh);

  // Border (hairline)
  const borderGeometry = new EdgesGeometry(cardGeometry);
  const borderMaterial = new LineBasicMaterial({ color: BORDER_COLOR });
  const borderLines = new LineSegments(borderGeometry, borderMaterial);
  root.add(borderLines);

  // ---------- Header Strip ----------
  const headerGeometry = new PlaneGeometry(CARD_W, HEADER_H, 1, 1);
  const headerMaterial = new MeshStandardNodeMaterial();
  headerMaterial.colorNode = color('#16161d');
  headerMaterial.metalness = 0.5;
  headerMaterial.roughness = 0.55;
  headerMaterial.clearcoat = 0.2;
  headerMaterial.transparent = true;
  const headerMesh = new Mesh(headerGeometry, headerMaterial);
  headerMesh.position.set(0, CARD_H / 2 - HEADER_H / 2, 0.001);
  root.add(headerMesh);

  // ---------- Text Creation Helper ----------
  const createTextMesh = (txt, style) => {
    // Expected ctx.fontAtlas API: create({text, size, family, weight, color})
    const mesh = ctx.fontAtlas.create({
      text: txt,
      size: style.fontSize,
      family: style.family,
      weight: style.fontWeight,
      color: style.color
    });
    // Ensure material is transparent for opacity animation
    if (mesh.material) {
      mesh.material.transparent = true;
      mesh.material.depthWrite = false;
    }
    return mesh;
  };

  // Palette colors
  const PAPER_COLOR = '#e8ecf2';

  // ---------- Tier Name ----------
  const tierNameStyle = {
    family: 'JetBrains Mono',
    fontSize: 0.20, // scaled to scene units (using typographic scale)
    fontWeight: 700,
    color: PAPER_COLOR
  };
  const tierNameMesh = createTextMesh('ATELIER RESERVE', tierNameStyle);
  tierNameMesh.position.set(0, CARD_H / 2 - HEADER_H - PADDING - 0.2, 0.002);
  root.add(tierNameMesh);

  // ---------- Price ----------
  const priceStyle = {
    family: 'Lora',
    fontSize: 0.62,
    fontWeight: 600,
    color: PAPER_COLOR
  };
  const priceMesh = createTextMesh('$480', priceStyle);
  priceMesh.position.set(0, tierNameMesh.position.y - 0.35, 0.002);
  root.add(priceMesh);

  // ---------- Caption ----------
  const captionStyle = {
    family: 'JetBrains Mono',
    fontSize: 0.09,
    fontWeight: 400,
    color: PAPER_COLOR
  };
  const captionMesh = createTextMesh('PER MONTH, BILLED ANNUALLY', captionStyle);
  captionMesh.position.set(0, priceMesh.position.y - 0.25, 0.002);
  root.add(captionMesh);

  // ---------- Features ----------
  const featureTexts = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing'
  ];
  const featureStyle = {
    family: 'JetBrains Mono',
    fontSize: 0.13,
    fontWeight: 400,
    color: PAPER_COLOR
  };
  const featureMeshes = [];
  let featureBaseY = captionMesh.position.y - 0.5; // start after gap
  featureTexts.forEach((txt, idx) => {
    const mesh = createTextMesh(txt, featureStyle);
    const finalY = featureBaseY - idx * (FEATURE_ROW_H + FEATURE_GAP);
    mesh.position.set(0, finalY + 0.2, 0.002); // start offset for animation
    mesh.material.opacity = 0;
    featureMeshes.push({ mesh, finalY });
    root.add(mesh);
  });

  // ---------- CTA Button ----------
  const ctaGeometry = new PlaneGeometry(CTA_W, CTA_H, 1, 1);
  const ctaMaterial = new MeshStandardNodeMaterial();
  // Gradient using tsl nodes
  ctaMaterial.colorNode = mix(color('#ff4450'), color('#c1121f'), uv().y);
  ctaMaterial.emissiveNode = mul(color('#ff2a38'), float(1.5));
  ctaMaterial.metalness = 0.0;
  ctaMaterial.roughness = 0.5;
  ctaMaterial.transparent = true;
  const ctaMesh = new Mesh(ctaGeometry, ctaMaterial);
  ctaMesh.position.set(
    0,
    -CARD_H / 2 + CTA_OFFSET_FROM_BOTTOM + CTA_H / 2,
    0.002
  );
  root.add(ctaMesh);

  const ctaLabelStyle = {
    family: 'JetBrains Mono',
    fontSize: 0.13,
    fontWeight: 700,
    color: PAPER_COLOR
  };
  const ctaLabelMesh = createTextMesh('JOIN THE RESERVE', ctaLabelStyle);
  ctaLabelMesh.position.set(0, ctaMesh.position.y, 0.003);
  root.add(ctaLabelMesh);

  // ---------- Animations ----------
  const timeline = gsap.timeline({ defaults: { ease: 'power4.out' } });

  // weighted-settle scale animation
  root.scale.set(1.04, 1.04, 1.04);
  timeline.to(
    root.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)'
    },
    0
  );

  // feature rows staggered fade-up
  featureMeshes.forEach((item, i) => {
    const delay = 0.08 * i;
    timeline.to(
      item.mesh.material,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      },
      delay
    );
    timeline.to(
      item.mesh.position,
      {
        y: item.finalY,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      },
      delay
    );
  });

  // Store cleanup resources
  const disposables = [
    cardGeometry,
    cardMaterial,
    headerGeometry,
    headerMaterial,
    ctaGeometry,
    ctaMaterial,
    borderGeometry,
    borderMaterial,
    ...featureMeshes.map(f => f.mesh.geometry),
    ...featureMeshes.map(f => f.mesh.material)
  ];

  // Expose userData
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timeline.kill();
    disposables.forEach(d => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    // Dispose text meshes if they expose dispose
    [tierNameMesh, priceMesh, captionMesh, ...featureMeshes.map(f => f.mesh), ctaLabelMesh].forEach(m => {
      if (m && m.geometry && typeof m.geometry.dispose === 'function') m.geometry.dispose();
      if (m && m.material && typeof m.material.dispose === 'function') m.material.dispose();
    });
  };

  // Apply cinematic primitives if any (none in this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(prim => {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') fn(root, prim.params);
    });
  }

  return root;
}
